{"explanation":"Think of x² as an x-by-x square. Split 6x into two 3-by-x rectangles and place them along two sides: the shape is almost a square, but its corner is missing a 3-by-3 piece. Adding that area of 9 completes a square of side x+3, so x²+6x=(x+3)²−9.","manimCode":"const unit = 0.7;
const left = -5.5;
const bottom = -2.45;
let x = 2.5;

function rectangle(x1, y1, x2, y2) {
  return [[x1,y1,0],[x2,y1,0],[x2,y2,0],[x1,y2,0]];
}
function regions() {
  const edge = left + unit*x;
  const top = bottom + unit*x;
  const farRight = edge + 3*unit;
  const farTop = top + 3*unit;
  return {
    square: rectangle(left,bottom,edge,top),
    right: rectangle(edge,bottom,farRight,top),
    upper: rectangle(left,top,edge,farTop),
    corner: rectangle(edge,top,farRight,farTop),
    edge, top, farRight, farTop
  };
}
const r = regions();
const square = new Polygon({ vertices: r.square, color: BLUE });
square.setFill(BLUE, 0.48).setStrokeWidth(3);
const rightRect = new Polygon({ vertices: r.right, color: TEAL });
rightRect.setFill(TEAL, 0.48).setStrokeWidth(3);
const upperRect = new Polygon({ vertices: r.upper, color: TEAL });
upperRect.setFill(TEAL, 0.48).setStrokeWidth(3);
const corner = new Polygon({ vertices: r.corner, color: GOLD });
corner.setFill(GOLD, 0.38).setStrokeWidth(3);

const title = new Text({ text: 'Completing the square', color: WHITE, fontSize: 34 });
title.moveTo([0,3.2,0]);
const squareLabel = new Text({ text: 'x²', color: WHITE, fontSize: 30 });
const rightLabel = new Text({ text: '3x', color: WHITE, fontSize: 28 });
const upperLabel = new Text({ text: '3x', color: WHITE, fontSize: 28 });
const cornerLabel = new Text({ text: '+9', color: WHITE, fontSize: 29 });
const xBottom = new Text({ text: 'x', color: BLUE_A, fontSize: 25 });
const threeBottom = new Text({ text: '3', color: GOLD, fontSize: 25 });
const xLeft = new Text({ text: 'x', color: BLUE_A, fontSize: 25 });
const threeLeft = new Text({ text: '3', color: GOLD, fontSize: 25 });

function placeLabels() {
  const q = regions();
  squareLabel.moveTo([(left+q.edge)/2,(bottom+q.top)/2,0]);
  rightLabel.moveTo([(q.edge+q.farRight)/2,(bottom+q.top)/2,0]);
  upperLabel.moveTo([(left+q.edge)/2,(q.top+q.farTop)/2,0]);
  cornerLabel.moveTo([(q.edge+q.farRight)/2,(q.top+q.farTop)/2,0]);
  xBottom.moveTo([(left+q.edge)/2,bottom-0.38,0]);
  threeBottom.moveTo([(q.edge+q.farRight)/2,bottom-0.38,0]);
  xLeft.moveTo([left-0.35,(bottom+q.top)/2,0]);
  threeLeft.moveTo([left-0.35,(q.top+q.farTop)/2,0]);
}
placeLabels();

const completed = new MathTex({ latex: 'x^2+6x+9=(x+3)^2' });
await completed.waitForRender();
completed.moveTo([2.7,1.55,0]);
const result = new MathTex({ latex: 'x^2+6x=(x+3)^2-9' });
await result.waitForRender();
result.moveTo([2.7,0.45,0]);

scene.add(title);
await scene.play(new AnimationGroup([new DrawBorderThenFill(square), new DrawBorderThenFill(rightRect), new DrawBorderThenFill(upperRect)]));
scene.add(squareLabel,rightLabel,upperLabel,xBottom,threeBottom,xLeft,threeLeft);
await scene.play(new DrawBorderThenFill(corner));
scene.add(cornerLabel);
await scene.play(new AnimationGroup([new Write(completed), new Write(result)]));

const controls = new Controls(scene, { position: 'bottom-right', width: 260 });
controls.addSlider({ label: 'Length x', min: 1.5, max: 3.2, value: x, step: 0.1, onChange: (value) => {
  x = value;
  const q = regions();
  square.setVertices(q.square);
  rightRect.setVertices(q.right);
  upperRect.setVertices(q.upper);
  corner.setVertices(q.corner);
  placeLabels();
}});
await scene.wait(999999);"}

